<template>
    <div class="ecom__element ecom-element ecom-testimonials">
        <div class="ecom-testimonials--container ecom-swiper-a11y-host">
            <button
                v-if="$helpers.hasAutoplayToggle(data.settings)"
                type="button"
                class="ecom-swiper-autoplay-toggle"
                :data-position="data.settings?.a11y_autoplay_control_position || 'bottom-right'"
                data-state="playing"
                data-label-pause="Pause automatic slide show"
                data-label-play="Start automatic slide show"
                aria-label="Pause automatic slide show"
            >
                <svg class="ecom-swiper-autoplay-toggle__pause" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5h3v14H8zM13 5h3v14h-3z"/></svg>
                <svg class="ecom-swiper-autoplay-toggle__play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5v14l11-7z"/></svg>
            </button>
            <div
                class="ecom__testimonials ecom-html"
                :class="{
                    'ecom-swiper-container ecom-d-hide':
                        testimonials.settings && testimonials.settings.layout !== 'grid'
                }"
            >
                <div
                    :class="
                        testimonials.settings && testimonials.settings.layout == 'grid'
                            ? 'ecom__testimonials--grid'
                            : 'ecom-swiper-wrapper ecom__testimonials-slider-' + slider_layout
                    "
                >
                    <!-- Slides -->
                    <template v-if="data.settings && data.settings.items">
                        <div
                            v-for="(item, index) in data.settings.items"
                            :key="index"
                            :class="[
                                testimonials.settings.layout == 'grid' ? 'ecom-testimonial-item': 'ecom-swiper-slide',
                                data.settings?.style == 0 ? 'ecom-flex' : ''
                            ]
                            "
                        >
                            <div
                                v-if="data.settings?.style == 0"
                                class="testimonial-info-avatar"
                            >
                                <figure
                                    v-if="item.image"
                                    class="ecom-element ecom-base-testimonial-image ecom-image-default"
                                >
                                    <img :src="item.image.value" :alt="item.image.name" :loading="lazyload ? 'lazy' : 'auto'"/>
                                </figure>
                            </div>
                            <div class="testimonial-content" :style="data.settings?.style == 0 ? 'flex: 1' : ''">
