                                </div>
                                <div class="testimonial-info" :class="data?.settings?.imagePos" :style="'order:' + styleView.infor">
                                    <div
                                        v-if="data.settings?.style != 0"
                                        class="testimonial-info-avatar ecom-image-align"
                                    >
                                        <figure
                                            v-if="item.image"
                                            class="ecom-element ecom-base-testimonial-image ecom-image-default"
                                        >
                                            <img :src="item.image.value" :alt="item.image.name" :loading="lazyload ? 'lazy' : 'auto'"/>
