                            </div>
                        </div>
                    </template>
                </div>
            </div>
            <div
                        v-if="isNavigation && isCombined() == 'combine'"
                        class="ecom-swiper-navigation"
                        :data-navigator-type="isCombined() == 'combine'"
                    >
                <div class="ecom-flex-center">
                    <button
                        v-show="isArrow()"
                        class="ecom-swiper-button ecom-swiper-button-prev"
                        v-html="slider.settings.slider_prev_icon"
                    />
                    <div v-show="isPagination()" class="ecom-swiper-pagination" />
                    <button
                        v-show="isArrow()"
                        class="ecom-swiper-button ecom-swiper-button-next"
                        v-html="slider.settings.slider_next_icon"
                    />
                </div>
            </div>
            <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isArrow()" class="ecom-swiper-navigation-position">
                <button
                    :style="sliderNav"
                    class="ecom-swiper-button ecom-swiper-button-prev"
                    v-html="slider.settings.slider_prev_icon"
                />
                <button
                    :style="sliderNav"
                    class="ecom-swiper-button ecom-swiper-button-next"
                    v-html="slider.settings.slider_next_icon"
                />
            </div>
            <div v-if="isNavigation && !(isCombined() == 'combine')" v-show="isPagination()" class="ecom-swiper-pagination-position ecom-swiper-pagination" :data-ecnav-id="data?.id" />
        </div>
    </div>
  </template>

  <script>
  import { Element, Javascript } from "@/mixins";
  export default {
    name: "Testimonials",
    presets:true,
    mixins: [Element, Javascript],
    vendors: ["slider_js", "slider_css"],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },

    data() {
        return {
            jsreactives: ["layout", "items", "imagePos", 'style', 'containerHeight', 'slider_layout']
        };
    },

    computed: {
        slider(){ return this.data;},
        slider_layout() {
            return this.data.settings?.slider_layout || 'horizontal'
        },
        css() {
            return `
${this.$helpers.autoplayToggleCss()}
                    .ecom-flex-center, .ecom-swiper-navigation {
                        display: flex;
                        align-items: center;
                    }
                    .ecom-swiper-navigation-position{
                        display:flex;
                    }
                    .ecom-swiper-navigation-position button{
                        margin:0
                    }
                    .ecom-swiper-navigation{
                        justify-content: center
                    }
                    .ecom-testimonials--container {
                        position: relative;
                        display: flex;
                        flex-direction: column;
                    }
                    .ecom-swiper-navigation[data-navigator-type="combine"]{
                        justify-content: center
                    }
                    .ecom-testimonials--container .ecom-swiper-button-next:after,
                    .ecom-testimonials--container .ecom-swiper-button-prev:after {
                        content: none;
                    }
                    .ecom-testimonials--container .ecom-swiper-button-next,
                    .ecom-testimonials--container .ecom-swiper-button-prev {
                        border: 0;
                        background: transparent;
                        width: auto;
                        height: auto;
                        padding: 5px;
                        color: #444
                    }
                    .ecom-testimonials--container .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-next,
                    .ecom-testimonials--container .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-prev {
                        position: static;
                        margin: 0;
                    }
                    .ecom-testimonials--container .ecom-swiper-navigation[data-navigator-type="classic"] .ecom-swiper-pagination,
                    .ecom-testimonials--container .ecom-swiper-navigation:not([data-navigator-type]) .ecom-swiper-pagination {
                        width:100%
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination:not(.ecom-swiper-pagination-progressbar) {
                        position: relative;
                    }
                    .ecom-swiper-pagination-bullet:only-child {
                        opacity: none
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination-bullet {
                        width: 15px;
                        height: 15px;
                        opacity: 1
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination-bullet,
                    .ecom-testimonials--container .ecom-swiper-pagination-bullet-active{
                        background-clip: content-box;
                        padding: 1px;
                        box-sizing: content-box !important;
                        background-color: currentColor;
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination-bullets{
                        width:auto;
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination-bullet img{
                        display: block;
                        width: 100%;
                        height: 100%;
                        object-fit: cover
                    }
                    .ecom-testimonials--container .ecom-swiper-pagination-bullets, .ecom-swiper-pagination-custom, .ecom-swiper-pagination-fraction {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        bottom: 0;
                    }
                    .ecom-d-hide {
                        opacity: 0;
                    }
                    .ecom__testimonials {
                        width: 100%;
                    }
                    .ecom__testimonials .testimonial-content {
                        position: relative;
                        display:flex;
                        flex-direction:column
                    }
                    .ecom__testimonials .ecom__testimonials--grid {
                        display: grid;
                    }
                    .ecom-text-left {
                        text-align: left
                    }
                    .ecom-text-center {
                        text-align: center
                    }
                    .ecom-text-right {
                        text-align: right
                    }
                    .ecom__testimonials .ecom-base-testimonial-image figure {
                        display: block;
                    }
                    .testimonial-rating {
                        display: flex;
                        flex-wrap: wrap;
                        justify-content:inherit;
                    }
                    .ecom-row-center{
                        display: inline-flex;
                        flex-direction: row;
                        align-items: center;
                        justify-content:center
                    }
                    .ecom-column-center{
                        display: flex;
                        flex-direction: column;
                        justify-content:inherit;
                    }
                    .ecom-column-center > .testimonial-info-avatar{
                        justify-content:inherit;
                        display:flex;
                    }
                    .ecom-icon-list span svg{
                        width:24px;
                        height:auto;
                    }
                     .testimonial-content .ecom-base-testimonial-image{
                         overflow:hidden;
                         display:flex;
                     }
                     .testimonial-content .ecom-base-testimonial-image img{
                         width:100%;
                     }

                     .testimonial-quote svg{
                        width:24px;
                        height:auto
                     }
                     .ecom-swiper-pagination{
                         display:flex;
                         flex-wrap:wrap;
                     }
                     .ecom-testimonial-rating-position{
                         display:flex;
                         flex-direction:column
                     }
                     .testimonial-content-prag ul {
                        list-style-type: disc;
                        list-style-position: inside;
                    }
                    .testimonial-content-prag ol {
                        list-style-type: decimal;
                        list-style-position: inside;
                    }
                    .testimonial-content-prag ul ul,
                    .testimonial-content-prag ol ul {
                        list-style-type: circle;
                        list-style-position: inside;
                        margin-left: 15px;
                    }
                    .testimonial-content-prag ol ol,
                    .testimonial-content-prag ul ol {
                        list-style-type: lower-latin;
                        list-style-position: inside;
                        margin-left: 15px;
                    }
                    .ecom-swiper-button > svg{
                        width:36px;
                        height:36px;
                    }
                    .testimonial-rating >span{
                        display:flex
                    }
                    .ecom__testimonials-slider-vertical {
                        flex-direction: column
                    }
                    .ecom__testimonials-slider-vertical .ecom-swiper-slide {
                        height: 100%;
                    }
                    .ecom-swiper-navigation-position .ecom-swiper-button {
                      position: var(--ecom-position);
                    }
                    @media (max-width: 1024px) {
                        .ecom-swiper-navigation-position .ecom-swiper-button {
                        position: var(--ecom-position__tablet);
                      }
                    }
                    @media (max-width: 767px) {
                        .ecom-swiper-navigation-position .ecom-swiper-button {
                        position: var(--ecom-position__mobile);
                      }
                    }
                `;
        },
        optionSwiper() {
            return this.$helpers.optionSwiper(this.data.settings);
        },
        javascript() {
            return function () {
                // Nút pause autoplay (WCAG 2.2.2). Đọc $container.swiper lúc click
                // nên không phụ thuộc thứ tự init của slider bên dưới.
                var $ecomAptg = this.$el && this.$el.querySelector('.ecom-swiper-autoplay-toggle');
                if ($ecomAptg && !$ecomAptg.getAttribute('data-ecom-bound')) {
                    $ecomAptg.setAttribute('data-ecom-bound', '1');
                    var $ecomAptgBox = this.$el.querySelector('.ecom-swiper-container');
                    $ecomAptg.addEventListener('click', function () {
                        var sw = $ecomAptgBox && $ecomAptgBox.swiper;
                        if (!sw || !sw.autoplay) return;
                        if (sw.autoplay.running) {
                            // stop() chứ không pause(): pause() sẽ bị resume() của
                            // pauseOnMouseEnter bật lại, người dùng bấm dừng phải dừng hẳn.
                            sw.autoplay.stop();
                            $ecomAptg.setAttribute('data-state', 'paused');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-play'));
                        } else {
                            sw.autoplay.start();
                            $ecomAptg.setAttribute('data-state', 'playing');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-pause'));
                        }
                    });
                }
                const $el = this.$el;
                if(!$el)
                {
                    return false;
                }
                const $container = $el.querySelector(".ecom-swiper-container");
                const settings = window.EComposer && typeof window.EComposer.normalizeSwiperSettings === 'function'
                    ? window.EComposer.normalizeSwiperSettings(this.settings)
                    : this.settings,
                    slider_loop = settings.slider_loop,
                    slider_center = settings.slider_center,
                    slider_center__tablet = settings.slider_center__tablet ?? settings.slider_center,
                    slider_center__mobile = settings.slider_center__mobile ?? settings.slider_center__tablet ?? settings.slider_center,
                    slider_group = settings.slider_group,
                    slider_items = settings.slider_items,
                    slider_group__tablet = settings.slider_group__tablet ?? settings.slider_group,
                    slider_items__tablet = settings.slider_items__tablet ?? settings.slider_items,
                    slider_group__mobile = settings.slider_group__mobile ?? settings.slider_group__tablet ?? settings.slider_group,
                    slider_items__mobile = settings.slider_items__mobile ?? settings.slider_items__tablet ?? settings.slider_items;
                if (!$container) {
                    return;
                }
                const _self = this;
                const _initSwiper = function() {
                    if(!(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function')) {
                        let _r = 0;
                        const _t = setInterval(function() {
                            _r++;
                            if(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function') { clearInterval(_t); _initSwiper(); }
                            else if(_r >= 20) clearInterval(_t);
                        }, 200);
                        return;
                    }
                var options = window.EComposer.buildSwiperConfig(settings);
                if(!options.navigation)
                {
                    options.navigation = {};
                }
                if(!options.pagination)
                {
                    options.pagination = {};
                }
                const handleResponsive = function(settings, optionSwiper = {}, option='') {
                if(option == 'loop') {
                  if(!settings.items) return optionSwiper;
                  if(window.innerWidth > 1024 && ((settings.items.length < slider_group + slider_items) || settings.slider_autoplay)) {
                    optionSwiper.loop = false;
                  }
                  else if((window.innerWidth <= 1024 && window.innerWidth > 768) && ((settings.items.length < slider_group__tablet + slider_items__tablet) || settings.slider_autoplay)) {
                    optionSwiper.loop = false;
                  }
                  else if((settings.items.length < slider_group__mobile + slider_items__mobile) || settings.slider_autoplay) {
                    optionSwiper.loop = false;
                  }
                  return optionSwiper;
                }
                else {
                  if(window.innerWidth > 1024 && settings.speed) {
                      optionSwiper[`${option}`] = settings[0];
                  }
                  if(window.innerWidth <= 1024 && window.innerWidth > 768 && settings[1]) {
                      optionSwiper[`${option}`] = settings[1];
                  }
                  else if(settings[0]) {
                      optionSwiper[`${option}`] = settings[0];
                  }
                  if (window.innerWidth < 768 && settings[2]) {
                      optionSwiper[`${option}`] = settings[2];
                  }
                  else if(settings[1]) {
                      optionSwiper[`${option}`] = settings[1];
                  }
                  else if(settings[0]) {
                      optionSwiper[`${option}`] = settings[0];
                  }
                  return optionSwiper;
                }
              }
                const paginationEl = $el.querySelector(`.ecom-swiper-pagination[data-ecnav-id="${_self.id}"]`);
                const nextEl = $el.querySelector('.ecom-swiper-button-next');
                const prevEl = $el.querySelector('.ecom-swiper-button-prev');
                options.pagination.el = paginationEl;
                options.navigation.nextEl = nextEl;
                options.navigation.prevEl = prevEl;
                options.pagination.renderBullet = (index, className) => {
                    return `<span class="${className}">
                            ${settings.items && settings.items[index] && settings.items[index].slider_pagination_image ?
                                `<img src="${settings.items[index].slider_pagination_image}" loading="lazy">` :
                                ''
                            }</span>`;
                }
                options.on = {
                    init: () => {
                        setTimeout(() => {
                            $container.classList.remove("ecom-d-hide");
                        });
                    }
                };
                if(slider_loop) {
                    options.loop = true;
                    options = handleResponsive(settings, options, 'loop');
                }
                let settings_center = [slider_center, slider_center__tablet, slider_center__mobile];
                options = handleResponsive(settings_center, options, 'centeredSlides');
                if(_self.settings.hasOwnProperty('slider_layout') && _self.settings.slider_layout == 'vertical') {
                    options.direction = 'vertical';
                }
                // eslint-disable-next-line no-new
                new window.EComSwiper(
                    $container,
                    Object.assign(options, { allowTouchMove: _self.isLive })
                );
                window.addEventListener("resize", () => {
                    $container.swiper.update();
                });
                }; // end _initSwiper
                _initSwiper();
            };
        },

        paginationImages() {
            return this.testimonials.settings?.items?.map(item => item.slider_pagination_image);
        },
        lazyload() {
          return this.data.settings?.disable_lazyload === true ? false : true;
        },

        settings() {
            return [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            name: "items",
                            label: this.$t('testimonials_items'),
                            type: "group",
                            value: [],
                            options: {
                                add_text: this.$t('add_item'),
                                is_clear_all: false
                            },
                            params: [
                                {
                                    type: "picker",
                                    label: this.$t('avatar'),
                                    name: "image",
                                    options: {
                                        type: "image",
                                        output: ["value", "name"],
                                        editAlt: true
                                    }
                                },
                                {
                                    type: "toggle",
                                    name: "useRating",
                                    label: this.$t('use_rating'),
                                    options: {
                                        values: {
                                            on: {
                                                label: this.$t('yes'),
                                                value: true
                                            },
                                            off: {
                                                label: this.$t('no'),
                                                value: false
                                            }
                                        }
                                    }
                                },
                                {
                                    type: "choose",
                                    name: "rating",
                                    label: this.$t('rating'),
                                    options: {
                                        chooseOne:true,
                                        type: "rating",
                                        visible: {
                                            keep_data: true,
                                            condition: (data) => data["useRating"]
                                        }
                                    }
                                },
                                {
                                    type: "picker",
                                    name: "ratingIcon",
                                    label: this.$t('icon'),
                                    options: {
                                        type: "icon",
                                        output: "value",
                                        visible: {
                                            keep_data: true,
                                            condition: (data) => data["useRating"]
                                        }
                                    }
                                },
                                {
                                    type: "picker",
                                    label: this.$t('quote_icon'),
                                    name: "quote",
                                    options: {
                                        type: "icon",
                                        output: "value"
                                    }
                                },
                                {
                                    type: "text",
                                    label: this.$t('name'),
                                    name: "name"
                                },
                                {
                                    type: "text",
                                    label: this.$t('title'),
                                    name: "title"
                                },
                                {
                                    type: "textarea",
                                    label: this.$t('text'),
                                    name: "text",
                                    options: {
                                        toolbar: "short",
                                        height: 180
                                    }
                                },
                                {
                                    type: 'picker',
                                    label: this.$t('pagination_image'),
                                    name: 'slider_pagination_image',
                                    options: {
                                        type: 'image',
                                        output: 'value',
                                        visible: {
                                            keep_data: false,
                                            condition: (data, datas, values = this.data.settings) => {
                                                return (
                                                        values["slider_navigation_layout"] === "classic_full" ||
                                                        values["slider_navigation_layout"] === "neo_full" ||
                                                        values["slider_navigation_layout"] === "pagination"
                                                    ) && values['slider_pagination_style_have_image'] === 'images';
                                            }
                                        }
                                    }
                                },
                            ]
                        },
                        {
                            type: "line"
                        },
                        {
                            type: 'popup',
                            name: 'name_tag',
                            label: this.$t('html_tag_for_customer_name'),
                            value: 'h3',
                            options: {
                                default: false,
                                preview: 'title',
                                type: 'dropdown',
                                values: {
                                    h1: 'H1',
                                    h2: 'H2',
                                    h3: 'H3',
                                    h4: 'H4',
                                    h5: 'H5',
                                    h6: 'H6',
                                    div: 'DIV',
                                    p: 'P'
                                }
                            }
                        },
                        {
                            type: 'popup',
                            name: 'title_tag',
                            label: this.$t('html_tag_for_title'),
                            value: 'h4',
                            options: {
                                default: false,
                                preview: 'title',
                                type: 'dropdown',
                                values: {
                                    h1: 'H1',
                                    h2: 'H2',
                                    h3: 'H3',
                                    h4: 'H4',
                                    h5: 'H5',
                                    h6: 'H6',
                                    div: 'DIV',
                                    p: 'P'
                                }
                            }
                        },
                        {
                            type: 'toggle',
                            name: 'disable_lazyload',
                            label: this.$t('disable_lazyload'),
                            options: {
                                oneline: true,
                                values: {
                                    off: {
                                        label: this.$t('no'),
                                        value: false
                                    },
                                    on: {
                                        label: this.$t('yes'),
                                        value: true
                                    }
                                }
                            },
                            css: {
                                isCss: false
                            }
                        },
                        {
                            label: this.$t('image_position'),
                            name: "imagePos",
                            type: "dropdown",
                            options: {
                                preview: 'title',
                                values: {
                                    "ecom-row-center": this.$t('aside'),
                                    "ecom-column-center": this.$t('top')
                                },
                                default: false,
                                half: true
                            }
                        },
                        {
                            type: "dropdown",
                            label: this.$t('view_layout'),
                            name: "layout",
                            value: "slider",
                            options: {
                                half: true,
                                default: false,
                                preview:'title',
                                values: {
                                    grid: this.$t('grid'),
                                    slider: this.$t('slider'),
                                }
                            }
                        },
                        {
                            type: "popup",
                            label: this.$t('style_layout'),
                            name: "style",
                            options: {
