                            options: {
                                type: "border",
                                oneline: true,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["tab"] === "hover";
                                    }
                                }
                            },
                            css: {
                                selector: ":hover"
                            }
                        },
                        {
                            name: "borderRadiusHoverMode",
                            label: this.$t('border_radius'),
                            type: "dimension",
                            options: {
                                type: "radius",
                                responsive: true,
                                units: "default",
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["tab"] === "hover";
                                    }
                                }
                            },
                            css: {
                                selector: ":hover",
                                properties: {
                                    "border-radius": ""
                                }
                            }
                        },
                        {
                            type: "number",
                            label: this.$t('transition_duration_span_class_lowercase_ms_span'),
                            name: "transition",
                            options: {
                                min: 0,
                                max: 1500,
                                visible: {
                                    keep_data: true,
                                    condition: (data) => {
                                        return data["tab"] === "hover";
                                    }
                                }
                            },
                            css: {
                                properties: {
                                    transition: "all %value%ms ease"
                                }
                            }
                        },
                        {
                            type: "line"
                        },
                        {
                            alias: 'spacing',
                            options: {
                                label: this.$t('spacing'),
                            }
                        }
                    ]
                },
                {
                    group_alias: 'box:active',
                    options: {
                        group_title: this.$t('slide'),
                        selector: ' .ecom-swiper-slide'
                    },
                    modify: {
                        params: {
                            position: 50,
                            fields: [{ type: 'line' },{
                                alias: 'spacing',
                                options: {
                                    label: this.$t('spacing'),
                                }
                            }]
                        },
                        // remove: {
                        //     label: this.$t('box_shadow'),
                        // }
                    }
                },
                this.checkVisible("rating")
                    ? {
                          group_alias: "icon:active",
                          options: {
                              group_name: "ratingIcon",
                              group_title: this.$t('rating_icon'),
                              selector: " .ecom-icon-list span"
                          },
                          modify: {
                              params: [
                                    {
                                        position: 0,
                                        fields: [
                                            {
                                                alias: 'justify-content',
                                                options: {
                                                    label: this.$t('alignment'),
                                                    css: {
                                                        selector: 'root .testimonial-rating.ecom-icon-list'
                                                    }
                                                }
                                            }
                                        ]
                                    },
                                  {
                                      position: 25,
                                      fields: [
                                          {
                                              type: "line",
                                              css: {
                                                  isCss: false
                                              }
                                          },
                                          {
                                              alias: "spacing",
                                              options: {
                                                label: this.$t('spacing'),
                                                  selector: "root .ecom-icon-list"
                                              }
                                          }
                                      ]
                                  }
                              ]
                          }
                      }
                    : null,
                this.checkVisible("quote")
                    ? {
                          group_alias: "icon",
                          options: {
                              group_name: "quoteIcon",
                              group_title: this.$t('quote_icon'),
                              selector: " .testimonial-quote"
                          },
                          modify: {
                              params: [
                                  {
                                      position: 15,
                                      fields: {
                                          alias: "spacing",
                                          options: {
                                            label: this.$t('spacing'),
                                          }
                                      }
                                  }
                              ]
                          }
                      }
                    : null,
                this.checkVisible("image")
                    ? {
                          group_alias: "image",
                          options: {
                              group_name: "image",
                              group_title: this.$t('image'),
                              selector: " .ecom-base-testimonial-image"
                          },
                          modify: {
                              params: [
                                {
                                    position: 0,
                                    fields: [
                                        {
                                            name: "imageAlign",
                                            label: this.$t('vertical_align'),
                                            type: "choose",
                                            options: {
                                                type: 'align-y-full',
                                                values: [
                                                    "flex-start",
                                                    "center",
                                                    "flex-end"
                                                ]
                                            },
                                            css: {
                                                selector: "root  .testimonial-info-avatar",
                                                properties: {
                                                    'align-items': '',
                                                    display: 'flex'
                                                }
                                            }
                                        },
                                    ]
                                },
                                {
                                    position: 50,
                                    fields: [
                                        {
                                            alias: "spacing",
                                            options: {
                                                label: this.$t('spacing'),
                                                selector: "root .ecom-image-default"
                                            }
                                        }
                                    ]
                                }
                              ]
                          }
                      }
                    : null,
                this.checkVisible("name")
                    ? {
                          group_alias: "text",
                          options: {
                              group_name: "name",
                              group_title: this.$t('name'),
                              selector: " .testimonial-content-name"
                          },
                          modify: {
                              params: [
                                  {
                                      position: 50,
                                      fields: [
                                          {
                                              type: "dimension",
                                              label: this.$t('spacing'),
                                              name: "spacing",
                                              options: {
                                                  responsive: true,
                                                  units: "default"
                                              },
                                              css: {
                                                  properties: {
                                                      spacing: ""
                                                  }
                                              }
                                          }
                                      ]
                                  }
                              ]
                          }
                      }
                    : null,
                this.checkVisible("title")
                    ? {
                          group_alias: "text",
                          options: {
                              group_name: "title",
                              group_title: this.$t('title'),
                              selector: " .testimonial-content-title"
                          },
                          modify: {
                              params: [
                                  {
                                      position: 50,
                                      fields: [
                                          {
                                              type: "dimension",
                                              label: this.$t('spacing'),
                                              name: "spacing",
                                              options: {
                                                  responsive: true,
                                                  units: "default"
                                              },
                                              css: {
                                                  properties: {
                                                      spacing: ""
                                                  }
                                              }
                                          }
                                      ]
                                  }
                              ]
                          }
                      }
                    : null,
                this.checkVisible("text")
                    ? {
                          group_alias: "text",
                          options: {
                              group_name: "text",
                              group_title: this.$t('content'),
                              selector: " .testimonial-content-prag"
                          },
                          modify: {
                              params: [
                                  {
                                      position: 5,
                                      fields: [
                                          {
                                              type: "background",
                                              name: "background",
                                              label: this.$t('background'),
                                          },
                                          {
                                              name: "contentWidth",
                                              label: this.$t('width'),
                                              type: "number",
                                              options: {
                                                  units: {
                                                      px: { min: 100, max: 1200 },
                                                      "%": { min: 50, max: 100 }
                                                  }
                                              },
                                              css: {
                                                  properties: {
                                                      display: "inline-block",
                                                      width: ""
                                                  }
                                              }
                                          },
                                          {
                                              type: "dimension",
                                              label: this.$t('border_radius'),
                                              name: "border-radius",
                                              options: {
                                                  type: "radius",
                                                  units: "default"
                                              }
                                          },
                                          {
                                              alias: "spacing",
                                              options:{
                                                label: this.$t('spacing')
                                              }
                                          }
                                      ]
                                  }
                              ]
                          }
                      }
                    : null,
                checkNavPagination.length ? {
                        group_alias:checkNavPagination,
                        options:{
                            group_title: this.$t('navigation'),
                            selector:' .ecom-testimonials--container'
                        },
                        modify: modifyNavigation

                } : null,
                // Nút pause autoplay tồn tại độc lập với arrow/pagination nên phải
                // là group riêng, không gộp vào checkNavPagination (modifyNavigation
                // splice theo index, thêm field vào đó sẽ làm lệch các field khác).
                this.$helpers.hasAutoplayToggle(this.data?.settings) ? {
                        group_alias: 'swiper:autoplay',
                        options: {
                            group_title: this.$t('pause_button'),
                            selector: ' .ecom-testimonials--container'
                        }
                } : null
            ].filter((x) => x);
        }
    }
  };
  </script>
